record RegistrationSnapshot(
    string AoR, string Contact, DateTimeOffset ExpiresAt,
    string? LastSipMethod, int? LastResponseCode);

bool IsRecentlyAccepted(RegistrationSnapshot s, DateTimeOffset now) =>
    s.LastSipMethod == "REGISTER" &&
    s.LastResponseCode == 200 && now < s.ExpiresAt;
